import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-124: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short124', durationInSeconds: 32.1, fps: 30, width: 1080, height: 1920 };

const T = [4.4, 7.2, 13.2, 16.6, 20.4, 26.0].map((s) => secToFrame(s));
const CTA = secToFrame(30.1);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short124: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  const lines = [{ text: 'HAIKU 10¢' }, { text: 'FLASH 75¢', accent: true }];
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={T[0]}>
        <CoverImage src="projects/short-124/cover.png" out={T[0] - 10} />
        <HookTitle hold onDark kicker="AI API PRICING" lines={lines} />
      </FadeOut>
      <FadeOut at={T[1]}>
        <ToolCard name="Claude Haiku 5.5" tagline="Per 1M tokens." chip="$0.10" at={T[0] - 2}>
          <Panel>
            <Line k="input /1M" v="$0.10" good />
            <Line k="output /1M" v="$0.50" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={T[2]}>
        <ToolCard name="Gemini 3.8 Flash" tagline="Per 1M tokens." chip="$0.75" at={T[1] - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="input /1M" v="$0.75" bad />
            <Line k="output /1M" v="$3.75" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={T[3]}>
        <ToolCard name="7.5x more" tagline="Input and output." chip="7.5X" at={T[2] - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Haiku 5.5" v="$0.10 / $0.50" good />
            <Line k="Flash 3.8" v="$0.75 / $3.75" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={T[4]}>
        <ToolCard name="Haiku's low price" tagline="Prompts up to 100K." chip="100K" at={T[3] - 2}>
          <Panel>
            <Line k="up to 100K" v="$0.10 / $0.50" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={T[5]}>
        <ToolCard name="Past 100K tokens" tagline="Still cheaper than Flash." chip="$0.50" at={T[4] - 2}>
          <Panel>
            <Line k="Haiku 5.5" v="$0.50 / $2.50" good />
            <Line k="Flash 3.8" v="$0.75 / $3.75" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="January 1" tagline="Flash doubles." chip="15X" at={T[5] - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Haiku 5.5" v="$0.10 / $0.50" good />
            <Line k="Flash 3.8" v="$1.50 / $7.50" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-124/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="AI API PRICING" lines={lines} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Cheap has a new name.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short124;
